package generator

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"slices"
	"strconv"
	"strings"
)

const heiryPath = "github.com/lucaf/heiry"

// marker returns the first line of the output generated for source. It also
// matches the go tool's convention for generated files.
func marker(source string) string {
	return "// Code generated by heirygen from " + source + "; DO NOT EDIT.\n"
}

// emitFile renders the generated file for one handwritten source file.
// taken holds the package-level identifiers of the package: the handwritten
// ones and every generated one.
func emitFile(source *sourceFile, taken map[string]bool) ([]byte, error) {
	// Identifiers the generated file must not redefine in a way that would
	// change what the spec's type expressions mean.
	avoid := make(map[string]bool)
	for name := range taken {
		avoid[name] = true
	}
	needsHeiry := false
	imports := &importSet{paths: make(map[string]string), bindings: make(map[string]binding)}
	for _, s := range source.specs {
		needsHeiry = needsHeiry || s.name != ""
		atConstant := reporter{report: func(message string) error { return errorAt(s.pos, "%s", message) }}
		for name := range s.identifiers() {
			avoid[name] = true
		}
		for name := range s.takenIdentifiers() {
			avoid[name] = true
		}
		// Each output imports what its own code uses, under the names it
		// uses: the spec's import lines, except those that only a chain's
		// levels or a part's component lines use, whose own output declares
		// nothing for them; then those that taken lines use, with the
		// meaning their own constants give them.
		for _, declared := range s.emittedImports() {
			avoid[declared.name] = true
			if err := imports.add(declared, atConstant); err != nil {
				return nil, err
			}
		}
		for _, use := range s.takenImports() {
			avoid[use.imported.name] = true
			if err := imports.add(use.imported, reporter{report: func(message string) error { return use.line.errorf("%s", message) }, taken: true}); err != nil {
				return nil, err
			}
		}
		avoid[s.constName] = true
		for _, set := range s.operations {
			for _, op := range set.ops {
				// Generated interfaces and the guards of existing ones copy
				// the signature.
				for _, needed := range op.method.imports {
					avoid[needed.name] = true
					if err := imports.add(needed, atConstant); err != nil {
						return nil, err
					}
				}
			}
		}
		for _, use := range s.existingUses {
			// The repeated guard copies the signature.
			for _, needed := range use.op.method.imports {
				avoid[needed.name] = true
				if err := imports.add(needed, atConstant); err != nil {
					return nil, err
				}
			}
		}
		if s.wrapper != nil {
			for _, op := range s.wrapper.privateOps {
				// The contract guard copies private signatures too.
				for _, needed := range op.method.imports {
					avoid[needed.name] = true
					if err := imports.add(needed, atConstant); err != nil {
						return nil, err
					}
				}
			}
			for _, op := range s.wrapper.forwards {
				// The forwarder names the operation interface, which another
				// specification may spell with its own imports.
				for _, needed := range append(op.method.imports, op.typeImports...) {
					avoid[needed.name] = true
					if err := imports.add(needed, atConstant); err != nil {
						return nil, err
					}
				}
			}
		}
	}
	names := emitNames{
		pkg:   free("heiry", avoid),
		leaf:  free("leaf", avoid),
		plan:  free("plan", avoid),
		fresh: free("generatedFrom", avoid),
		avoid: avoid,
	}
	names.unchanged = free("unchanged", avoid)

	var b bytes.Buffer
	b.WriteString(marker(source.name) + "\n")
	if source.buildConstraint != "" {
		fmt.Fprintf(&b, "%s\n\n", source.buildConstraint)
	}
	fmt.Fprintf(&b, "package %s\n\n", source.pkg)

	if needsHeiry || len(imports.order) != 0 {
		b.WriteString("import (\n")
		if needsHeiry {
			if names.pkg == "heiry" {
				fmt.Fprintf(&b, "\t%s\n", strconv.Quote(heiryPath))
			} else {
				fmt.Fprintf(&b, "\t%s %s\n", names.pkg, strconv.Quote(heiryPath))
			}
		}
		for _, name := range imports.order {
			fmt.Fprintf(&b, "\t%s %s\n", name, strconv.Quote(imports.paths[name]))
		}
		b.WriteString(")\n")
	}

	for _, s := range source.specs {
		emitFreshness(&b, s, names, "were generated from")
		for _, taken := range s.takenConstants() {
			emitFreshness(&b, taken, names, "also take lines from")
		}
		for _, set := range s.operations {
			emitOperations(&b, set)
		}
		if s.name != "" {
			emitHierarchy(&b, s, names)
		}
		if s.wrapper != nil {
			emitWrapper(&b, s, names)
		}
	}
	formatted, err := format.Source(b.Bytes())
	if err != nil {
		return nil, fmt.Errorf("internal error: the code generated for %s does not parse: %v", source.name, err)
	}
	return formatted, nil
}

// An importSet collects the imports of one generated file, each under an
// explicit name, with where each name was bound and how to report a
// conflict there.
type importSet struct {
	paths    map[string]string
	bindings map[string]binding
	order    []string
}

// A reporter reports a problem with an import's binding: at a taken line,
// naming the hierarchy that takes it, or at the specification's position.
type reporter struct {
	report func(string) error
	taken  bool
}

type binding struct {
	text string
	at   reporter
}

// add adds an import. A name bound to another path already is refused,
// naming both bindings. A conflict that a taken line causes is reported at
// that line, whichever binding came first; when both come from taken
// lines, at the one added second.
func (set *importSet) add(needed specImport, at reporter) error {
	if path, seen := set.paths[needed.name]; seen {
		if path != needed.path {
			first := set.bindings[needed.name]
			report := at.report
			if !at.taken && first.at.taken {
				report = first.at.report
			}
			return report(fmt.Sprintf("import name %s is used for %q and %q in one generated file, by %s, and by %s; give one of the imports another name", needed.name, path, needed.path, first.text, needed.binding()))
		}
		return nil
	}
	set.paths[needed.name] = needed.path
	set.bindings[needed.name] = binding{needed.binding(), at}
	set.order = append(set.order, needed.name)
	return nil
}

// emittedImports returns the spec's import lines that its own output's code
// uses: all of them, except for a chain or a part, whose levels or
// component lines its own output declares nothing for, so that only its
// existing lines count.
func (s *spec) emittedImports() []specImport {
	if s.chain == "" && s.part == "" {
		return s.imports
	}
	used := make(map[string]bool)
	for _, set := range s.operations {
		for _, entry := range set.existing {
			for _, declared := range s.importsOf(entry.typ) {
				used[declared.name] = true
			}
		}
	}
	var imports []specImport
	for _, declared := range s.imports {
		if used[declared.name] {
			imports = append(imports, declared)
		}
	}
	return imports
}

// A takenImport is an import that a taken line uses, and that line.
type takenImport struct {
	imported specImport
	line     specLine
}

// writtenExprs calls each with the type expressions of a spec's levels,
// each with the line it is written on, in the order of the written-out
// levels: each level line, then the level's node, component and use lines
// as they are written, each use line replaced by its part's component
// lines. A component slot's provider counts at every line that adds to the
// slot, each read with its own constant's imports, as the written-out form
// spells it on each.
func (s *spec) writtenExprs(each func(expr string, line specLine)) {
	type written struct {
		expr string
		line specLine
		at   [2]int // the line in the level's constant, then the part's line
	}
	for _, l := range s.levels {
		each(l.node, l.line)
		each(l.public, l.contracts)
		each(l.private, l.contracts)
		// The level's lines are numbered in the constant that writes the
		// level, and a part's lines sit at the use line that names the part.
		uses := make(map[*spec]int)
		for _, item := range l.items {
			if _, seen := uses[item.part]; item.part != nil && !seen {
				uses[item.part] = item.line
			}
		}
		var exprs []written
		add := func(expr string, line specLine) {
			at := [2]int{line.number, 0}
			if line.usedIn != nil {
				at = [2]int{uses[line.spec], line.number}
			}
			exprs = append(exprs, written{expr, line, at})
		}
		for index, sl := range l.slots {
			for at, op := range sl.ops {
				line := sl.lines[at]
				if index != 0 && (at == 0 || line.spec != sl.lines[at-1].spec || line.number != sl.lines[at-1].number) {
					add(sl.provider, line)
				}
				add(op, line)
			}
		}
		slices.SortStableFunc(exprs, func(a, b written) int { return slices.Compare(a.at[:], b.at[:]) })
		for _, e := range exprs {
			each(e.expr, e.line)
		}
	}
}

// takenExprs calls each with the type expressions of a hierarchy's lines
// that another constant holds, through from= or use, each with the line it
// is written on, in the order of the written-out hierarchy.
func (s *spec) takenExprs(each func(expr string, line specLine)) {
	if s.name == "" {
		// A chain's or part's own output declares nothing for its lines,
		// the taken ones included.
		return
	}
	s.writtenExprs(func(expr string, line specLine) {
		if line.spec != nil && line.spec != s {
			each(expr, line)
		}
	})
}

// takenImports returns the imports that taken lines use, each read with
// the imports of its own constant, in the order of first use.
func (s *spec) takenImports() []takenImport {
	var uses []takenImport
	seen := make(map[specImport]bool)
	s.takenExprs(func(expr string, line specLine) {
		for _, declared := range line.spec.importsOf(expr) {
			declared.used = false
			if !seen[declared] {
				seen[declared] = true
				uses = append(uses, takenImport{declared, line})
			}
		}
	})
	return uses
}

// takenIdentifiers returns the identifiers that taken lines use, which the
// output's local names must avoid as the written-out hierarchy's do.
func (s *spec) takenIdentifiers() map[string]bool {
	names := make(map[string]bool)
	s.takenExprs(func(expr string, _ specLine) {
		parsed, err := parser.ParseExpr(expr)
		if err != nil {
			return
		}
		ast.Inspect(parsed, func(n ast.Node) bool {
			if ident, ok := n.(*ast.Ident); ok {
				names[ident.Name] = true
			}
			return true
		})
	})
	return names
}

// emitNames are the identifiers the generated file introduces besides its
// package-level names.
type emitNames struct {
	pkg   string // import name of the heiry package
	leaf  string // leaf parameter
	plan  string // plan parameter
	fresh string // local constant holding the text the file was generated from
	// unchanged is the local constant that compares it with the spec constant.
	unchanged string
	avoid     map[string]bool
}

// free returns name, extended with underscores until it is not in avoid.
func free(name string, avoid map[string]bool) string {
	for avoid[name] {
		name += "_"
	}
	avoid[name] = true
	return name
}

// generatedNames lists the package-level identifiers one spec generates.
func (s *spec) generatedNames() []string {
	var names []string
	for _, set := range s.operations {
		for _, op := range set.ops {
			if op.generated {
				names = append(names, op.typ)
			}
		}
	}
	if s.name != "" {
		names = append(append(names, s.name), s.helpers()...)
	}
	if s.wrapper != nil {
		names = append(names, s.wrapper.name)
	}
	return names
}

// helpers lists the helper functions a hierarchy generates.
func (s *spec) helpers() []string {
	names := []string{s.name + "Refs", s.name + "Init"}
	if !s.omitInitPlan {
		names = append(names, s.name+"InitPlan")
	}
	return names
}

// emitFreshness writes the compile-time assertion that the spec constant
// still has the text the file was generated from. verb is "were generated
// from" for the output's own constant, and "also take lines from" for a
// constant whose lines a hierarchy takes.
func emitFreshness(b *bytes.Buffer, s *spec, n emitNames, verb string) {
	// The comparison is first bound to a constant, so the compiler has to
	// evaluate it: if the handwritten declaration stops being a constant,
	// that binding does not compile. When the two texts differ the constant
	// is false, the map literal has the key false twice, and the compiler
	// rejects it. The other key is written as a comparison and the key type
	// as an empty interface, so the assertion does not depend on what the
	// package makes of the names false and bool. The function is never
	// compiled into the program.
	fmt.Fprintf(b, "\n// The declarations below %s the constant %s.\n", verb, s.constName)
	fmt.Fprintf(b, "// If the map literal fails to compile with a duplicate key, %s has\n// changed since then: run go generate. If the line above it fails, %s\n// is no longer a constant.\n", s.constName, s.constName)
	fmt.Fprintf(b, "func _() {\n\tconst %s = \"\"", n.fresh)
	for _, line := range strings.SplitAfter(s.text, "\n") {
		if line != "" {
			fmt.Fprintf(b, " +\n\t\t%s", strconv.Quote(line))
		}
	}
	fmt.Fprintf(b, "\n\tconst %s = %s == %s\n", n.unchanged, s.constName, n.fresh)
	fmt.Fprintf(b, "\t_ = map[interface{}]struct{}{1 == 0: {}, %s: {}}\n}\n", n.unchanged)
}

// emitOperations writes one single-method interface per operation that has
// no existing interface.
func emitOperations(b *bytes.Buffer, set *operationSet) {
	generated := 0
	for _, op := range set.ops {
		if op.generated {
			generated++
		}
	}
	if generated != 0 {
		fmt.Fprintf(b, "\n// Operation interfaces of %s: one per method, with the\n// signature written in the contract.\n", strings.Join(set.contracts, ", "))
		b.WriteString("type (\n")
		for _, op := range set.ops {
			if op.generated {
				fmt.Fprintf(b, "\t%s interface{ %s%s }\n", op.typ, op.method.name, op.method.signature)
			}
		}
		b.WriteString(")\n")
	}
	// Two assignments per contract, one in each direction, are accepted only
	// when the contract and its operation interfaces have the same methods
	// with identical signatures. The compiler evaluates them against the
	// contracts as they are now, so a contract edited after generation, or
	// an interface the generator derived wrongly, does not compile.
	fmt.Fprintf(b, "\n// Each contract must have exactly the methods of its operation interfaces.\n")
	fmt.Fprintf(b, "// If an assignment below fails to compile, a contract no longer has the\n// methods this file was generated for: run go generate. If it still fails\n// afterwards, two listed contracts give one method name different\n// signatures, or an existing interface does not have the contract's.\n")
	b.WriteString("func _() {\n")
	for _, contract := range set.contracts {
		union := "interface{"
		for index, op := range set.contractOps[contract] {
			if index != 0 {
				union += "; "
			}
			union += op.typ
		}
		union += "}"
		fmt.Fprintf(b, "\tvar _ %s = %s(nil)\n", union, contract)
		fmt.Fprintf(b, "\tvar _ %s = %s(nil)\n", contract, union)
	}
	b.WriteString("}\n")
	// An existing interface is handwritten and can change in step with its
	// contract, which keeps the assertions above true. Two more assignments
	// tie it to the one method, with the signature, that it was named for.
	var existing []operation
	for _, op := range set.ops {
		if !op.generated {
			existing = append(existing, op)
		}
	}
	if len(existing) != 0 {
		fmt.Fprintf(b, "\n// Each existing interface must still have exactly the method it identifies.\n// If an assignment below fails to compile, it has changed since this file\n// was generated: run go generate, or correct its existing line.\n")
		b.WriteString("func _() {\n")
		for _, op := range existing {
			literal := methodsLiteral([]operation{op})
			fmt.Fprintf(b, "\tvar _ %s = %s(nil)\n", literal, op.typ)
			fmt.Fprintf(b, "\tvar _ %s = %s(nil)\n", op.typ, literal)
		}
		b.WriteString("}\n")
	}
}

// methodsLiteral returns an interface literal with the methods of the
// operations, each with the signature written in its contract.
func methodsLiteral(ops []operation) string {
	if len(ops) == 0 {
		return "interface{}"
	}
	methods := make([]string, len(ops))
	for index, op := range ops {
		methods[index] = op.method.name + op.method.signature
	}
	return "interface{ " + strings.Join(methods, "; ") + " }"
}

func emitHierarchy(b *bytes.Buffer, s *spec, n emitNames) {
	leaf := s.leaf
	fmt.Fprintf(b, "\n// %s is the receiver-free declaration of the hierarchy whose leaf is %s.\n", s.name, leaf)
	fmt.Fprintf(b, "var %s = %s.Define[%s]()", s.name, n.pkg, leaf)
	for _, level := range s.levels {
		fmt.Fprintf(b, ".\n\tLevel[%s, %s, %s](%s)", level.node, level.public, level.private, strconv.Quote(level.parent))
		for _, slot := range level.slots {
			for _, op := range slot.ops {
				fmt.Fprintf(b, ".\n\tBind[%s]((*%s)(nil), %s)", op, slot.provider, strconv.Quote(slot.path))
			}
		}
		b.WriteString(".\n\tEnd()")
	}
	b.WriteString("\n")

	result := fmt.Sprintf("[]%s.ProviderRef[%s]", n.pkg, leaf)
	planType := fmt.Sprintf("*%s.Plan[%s]", n.pkg, leaf)

	// The references are created by the definition, so they carry its
	// lineage whichever Plan they are passed to. Every factory call names
	// its type arguments, so the compiler checks each address against the
	// provider type the spec states.
	fmt.Fprintf(b, "\n// %sRefs returns one reference for every level node and registered\n// component of the object, created by %s.\n//\n", s.name, s.name)
	b.WriteString("// References cannot point into a nil object. For one, they point into a\n// scratch value instead: Init checks references before the object, and\n// well-formed references let it reach its own diagnostic for a nil object.\n")
	fmt.Fprintf(b, "func %sRefs(%s *%s) %s {\n", s.name, n.leaf, leaf, result)
	fmt.Fprintf(b, "\tif %s == nil {\n\t\t%s = new(%s)\n\t}\n", n.leaf, n.leaf, leaf)
	fmt.Fprintf(b, "\treturn %s{\n", result)
	for _, ref := range s.references() {
		if ref.path == "." {
			fmt.Fprintf(b, "\t\t%s.NodeProvider[%s](%s),\n", s.name, ref.provider, ref.address(n.leaf))
		} else {
			fmt.Fprintf(b, "\t\t%s.ComponentProvider[%s, %s](%s, %s),\n", s.name, ref.owner, ref.provider, strconv.Quote(ref.path), ref.address(n.leaf))
		}
	}
	b.WriteString("\t}\n}\n")

	fmt.Fprintf(b, "\n// %sInit binds one object through %s, preparing it on first use.\n", s.name, s.name)
	fmt.Fprintf(b, "func %sInit(%s *%s) error {\n", s.name, n.leaf, leaf)
	fmt.Fprintf(b, "\treturn %s.Init(%s, %sRefs(%s)...)\n}\n", s.name, n.leaf, s.name, n.leaf)

	if !s.omitInitPlan {
		fmt.Fprintf(b, "\n// %sInitPlan binds one object through a Plan prepared from %s or\n// converted from such a Plan, dynamic or precomputed. A Plan of another\n// definition is rejected by Init, because the references carry the lineage\n// of %s.\n", s.name, s.name, s.name)
		fmt.Fprintf(b, "func %sInitPlan(%s %s, %s *%s) error {\n", s.name, n.plan, planType, n.leaf, leaf)
		fmt.Fprintf(b, "\treturn %s.Init(%s, %sRefs(%s)...)\n}\n", n.plan, n.leaf, s.name, n.leaf)
	}

	emitProbes(b, s, n)

	if len(s.existingUses) != 0 {
		fmt.Fprintf(b, "\n// Each existing interface the registrations or forwarders of %s use must\n// still have exactly the method it identifies. If an assignment below fails\n// to compile, it has changed since this file was generated: run go generate,\n// or correct its existing line.\n", s.name)
		b.WriteString("func _() {\n")
		for _, use := range s.existingUses {
			literal := methodsLiteral([]operation{use.op})
			fmt.Fprintf(b, "\tvar _ %s = %s(nil)\n", literal, use.expr)
			fmt.Fprintf(b, "\tvar _ %s = %s(nil)\n", use.expr, literal)
		}
		b.WriteString("}\n")
	}
}

// emitProbes writes one probe per level after the root, for its parent
// field, and one per component, for the first field of its path in the
// owning node. The references select those fields by name, and a field that
// is promoted from an embedded struct still compiles there, although the
// library accepts only fields the struct declares itself: a promoted parent
// field means a level between the two is missing from the specification.
//
// Each probe embeds the struct beside a field of the same name two levels
// down, of type struct{}, as the holder guard does. A field the struct
// declares itself is the shallowest; one promoted from one level down makes
// the selector ambiguous, and one promoted from deeper selects the decoy,
// whose address has the wrong type. The struct is embedded through a local
// alias, because an embedded field is named after its type, and a node type
// named like the field would otherwise be what the selector finds. Later
// steps of a path are in types the specification does not name, so only the
// first step is probed.
func emitProbes(b *bytes.Buffer, s *spec, n emitNames) {
	type probe struct {
		comment         string
		owner, field    string // the struct, and the field it must declare
		selector, typed string // what the probe selects, and its type
	}
	// In an output whose hierarchy takes lines from other constants, each
	// probe's comment also names the constants where the fix can go.
	shared := len(s.takenConstants()) != 0
	var probes []probe
	for index, level := range s.levels {
		if index > 0 {
			parent := s.levels[index-1].node
			comment := fmt.Sprintf("%s declares its parent field %s, of type %s.", level.node, level.parent, parent)
			if shared {
				// A level missing before the first level of a constant whose
				// levels follow another's can go in either constant.
				comment += " Its level is in " + level.line.spec.constName
				if before := s.levels[index-1].line.spec; before != level.line.spec {
					comment += ", after the levels of " + before.constName
				}
				comment += "."
			}
			probes = append(probes, probe{
				comment: comment,
				owner:   level.node, field: level.parent, selector: level.parent, typed: parent,
			})
		}
		for _, slot := range level.slots[1:] {
			first, _, _ := strings.Cut(slot.path, ".")
			comment := fmt.Sprintf("%s declares the field %s of its component %s.", level.node, first, slot.path)
			if shared {
				comment += " " + slot.place()
			}
			probes = append(probes, probe{
				comment: comment,
				owner:   level.node, field: first, selector: slot.path, typed: slot.provider,
			})
		}
	}
	if len(probes) == 0 {
		return
	}
	if shared {
		b.WriteString("\n// Each probe below compiles only while a struct declares a field itself, as\n// the library requires: a level's parent field, and the first field of each\n// component's path. If a selector below is ambiguous or has another type,\n// that field is gone, has another type, or is reached only through another\n// embedded struct; for a parent field, a level between the two is then\n// missing from one of the constants that the probe's comment names.\n// Regenerating writes the same probes, so first correct a constant that the\n// probe's comment names, or the struct; then run go generate.\n")
	} else {
		fmt.Fprintf(b, "\n// Each probe below compiles only while a struct declares a field itself, as\n// the library requires: a level's parent field, and the first field of each\n// component's path. If a selector below is ambiguous or has another type,\n// that field is gone, has another type, or is reached only through another\n// embedded struct; for a parent field, a level between the two is then\n// missing from %s. Regenerating writes the same probes, so first correct\n// the levels or paths of %s, or the struct; then run go generate.\n", s.constName, s.constName)
	}
	for _, p := range probes {
		local := make(map[string]bool)
		for name := range n.avoid {
			local[name] = true
		}
		local[p.field] = true
		name, decoy, deeper, subject := free("probe", local), free("decoy", local), free("deeper", local), free("subject", local)
		fmt.Fprintf(b, "\n// %s\nfunc _() {\n", p.comment)
		fmt.Fprintf(b, "\ttype %s = %s\n\ttype %s struct{ %s struct{} }\n\ttype %s struct{ %s }\n", subject, p.owner, decoy, p.field, deeper, decoy)
		fmt.Fprintf(b, "\tvar %s struct {\n\t\t*%s\n\t\t%s\n\t}\n\tvar _ *%s = &%s.%s\n}\n", name, subject, deeper, p.typed, name, p.selector)
	}
}

// place names the constants that hold a component slot's lines, each once,
// in written-out order, with the constant of the use line for a part's
// line: the sentence a probe's comment ends with.
func (sl slot) place() string {
	type written struct {
		spec   *spec
		number int
	}
	var places []string
	var holders []*spec
	lines := make(map[written]bool)
	for _, line := range sl.lines {
		lines[written{line.spec, line.number}] = true
		if slices.Contains(holders, line.spec) {
			continue
		}
		holders = append(holders, line.spec)
		place := line.spec.constName
		if line.usedIn != nil {
			// The fix can also be at the use line: the part may be used at
			// a level whose node lacks the field.
			place += ", used in " + line.usedIn.constName
		}
		places = append(places, place)
	}
	if len(lines) == 1 {
		return "Its component line is in " + places[0] + "."
	}
	// A comma closes each "used in" clause that another place follows.
	sentence := "Its component lines are in " + places[0]
	for index, place := range places[1:] {
		if strings.Contains(places[index], ", used in ") {
			sentence += ","
		}
		sentence += " and in " + place
	}
	return sentence + "."
}

// emitWrapper writes the public wrapper type and one forwarder per public
// operation.
func emitWrapper(b *bytes.Buffer, s *spec, n emitNames) {
	w := s.wrapper
	fmt.Fprintf(b, "\n// %s is the public wrapper of %s. It holds the object in a named field,\n// so nothing is promoted onto it, and forwards every operation of %s\n// through a virtual call.\n", w.name, s.name, w.public)
	fmt.Fprintf(b, "type %s struct{ %s *%s }\n", w.name, w.field, s.leaf)
	// The forwarders select the holder by name. An edit of the leaf alone
	// could give that name to a pointer, perhaps into another object, which
	// makes the first address a **heiry.Node, or to a field promoted from an
	// embedded struct, which may belong to another object. The probe embeds
	// the leaf beside a field of the holder's name two levels down, of
	// another type: a field declared in the leaf is the shallowest, one
	// promoted from one level down makes the selector ambiguous, and one
	// promoted from deeper loses to the decoy, whose address is no
	// *heiry.Node. The probe embeds the leaf through a local alias, because
	// an embedded field is named after its type, and a leaf type named like
	// the holder, such as Node, would otherwise be what the selector finds.
	holderNames := make(map[string]bool)
	for name := range n.avoid {
		holderNames[name] = true
	}
	holderNames[w.holder] = true
	holderProbe, decoy, deeper, subject := free("probe", holderNames), free("decoy", holderNames), free("deeper", holderNames), free("subject", holderNames)
	fmt.Fprintf(b, "\n// The forwarders dispatch through %s.%s, which must still be a heiry.Node\n// declared in the leaf itself. If a line below fails to compile, that field\n// has changed since this file was generated: run go generate.\n", s.leaf, w.holder)
	fmt.Fprintf(b, "func _(%s *%s) {\n\tvar _ *%s.Node = &%s.%s\n", n.leaf, s.leaf, n.pkg, n.leaf, w.holder)
	fmt.Fprintf(b, "\ttype %s = %s\n\ttype %s struct{ %s struct{} }\n\ttype %s struct{ %s }\n", subject, s.leaf, decoy, w.holder, deeper, decoy)
	fmt.Fprintf(b, "\tvar %s struct {\n\t\t*%s\n\t\t%s\n\t}\n\tvar _ *%s.Node = &%s.%s\n}\n", holderProbe, subject, deeper, n.pkg, holderProbe, w.holder)
	fmt.Fprintf(b, "\n// *%s has every method of %s. This shows satisfaction only; it says\n// nothing about other methods of the wrapper.\n", w.name, w.public)
	fmt.Fprintf(b, "var _ %s = (*%s)(nil)\n", w.public, w.name)
	for _, op := range w.forwards {
		// Parameter names are kept when every parameter has one and none
		// could capture an identifier the body uses.
		local := make(map[string]bool)
		for name := range n.avoid {
			local[name] = true
		}
		keep := true
		for _, p := range op.method.params {
			if p.name == "" || p.name == "_" || local[p.name] {
				keep = false
			}
		}
		var names, args []string
		for index, p := range op.method.params {
			name := p.name
			if !keep {
				name = fmt.Sprintf("arg%d", index)
				for local[name] {
					name += "_"
				}
			}
			local[name] = true
			names = append(names, name)
			if p.variadic {
				name += "..."
			}
			args = append(args, name)
		}
		// The signature is rebuilt from the parameter and result types.
		// Result names are dropped: they are documentation in a contract,
		// and in a forwarder they could collide with the receiver or
		// capture a name the body uses.
		signature := op.method.signatureWith(names)
		receiver := "w"
		for local[receiver] {
			receiver += "_"
		}
		call := fmt.Sprintf("%s.%s.%s.Virtual[%s]().%s(%s)", receiver, w.field, w.holder, op.typ, op.method.name, strings.Join(args, ", "))
		if len(op.method.results) != 0 {
			call = "return " + call
		}
		fmt.Fprintf(b, "\nfunc (%s *%s) %s%s {\n\t%s\n}\n", receiver, w.name, op.method.name, signature, call)
	}
	if len(w.identities) != 0 {
		// A registration that spells a forwarder's interface differently,
		// through an alias, must denote the identical type: pointer types are
		// assignable only between identical element types.
		fmt.Fprintf(b, "\n// Each forwarder resolves the interface the hierarchy registers for its\n// operation. If an assignment below fails to compile, they are different\n// types: run go generate, or add an existing line.\n")
		b.WriteString("func _() {\n")
		for _, pair := range w.identities {
			fmt.Fprintf(b, "\tvar _ *%s = (*%s)(nil)\n", pair[0], pair[1])
		}
		b.WriteString("}\n")
	}
	// The leaf's contracts, compared with what they were when this file was
	// generated, in every build that compiles the wrapper. These do not go
	// through operation interfaces, which may be handwritten or declared in
	// a file that some builds leave out.
	fmt.Fprintf(b, "\n// The contracts of %s must still have exactly the methods this wrapper was\n// generated for. If an assignment below fails to compile, %s or %s has\n// changed since then: run go generate.\n", s.leaf, w.public, w.private)
	b.WriteString("func _() {\n")
	for _, contract := range []struct {
		name string
		ops  []operation
	}{{w.public, w.forwards}, {w.private, w.privateOps}} {
		literal := methodsLiteral(contract.ops)
		fmt.Fprintf(b, "\tvar _ %s = %s(nil)\n", literal, contract.name)
		fmt.Fprintf(b, "\tvar _ %s = %s(nil)\n", contract.name, literal)
	}
	b.WriteString("}\n")
	if len(w.privateOps) == 0 {
		return
	}
	// The probe embeds the wrapper and the private contract itself. A
	// wrapper method with the name of a private operation makes the
	// selector ambiguous, and a name the contract no longer has makes it
	// undefined. The wrapper struct has only its named field, so it
	// promotes nothing from deeper. The contract is embedded through a local
	// alias, because an embedded field is named after its type, and an
	// operation named like the contract would otherwise select that field.
	local := make(map[string]bool)
	for name := range n.avoid {
		local[name] = true
	}
	probe, contract := free("probe", local), free("contract", local)
	fmt.Fprintf(b, "\n// No method of %s may be named after an operation of %s.\n", w.name, w.private)
	fmt.Fprintf(b, "// If a selector below is ambiguous, a handwritten method of the wrapper\n// has the name of a private operation: remove or rename that method. If it\n// is undefined, %s no longer has that operation: run go generate.\n", w.private)
	fmt.Fprintf(b, "func _() {\n\ttype %s = %s\n\ttype %s struct {\n\t\t*%s\n\t\t%s\n\t}\n", contract, w.private, probe, w.name, contract)
	for _, op := range w.privateOps {
		fmt.Fprintf(b, "\t_ = %s.%s\n", probe, op.method.name)
	}
	b.WriteString("}\n")
}

// signatureWith returns the method's signature with the given parameter
// names and unnamed results.
func (m method) signatureWith(names []string) string {
	parts := make([]string, len(m.params))
	for index, p := range m.params {
		parts[index] = names[index] + " " + p.typ
	}
	signature := "(" + strings.Join(parts, ", ") + ")"
	switch len(m.results) {
	case 0:
		return signature
	case 1:
		return signature + " " + m.results[0]
	}
	return signature + " (" + strings.Join(m.results, ", ") + ")"
}

// A reference is one provider slot of the leaf object.
type reference struct {
	owner    string // owning level's node type
	provider string // provider type
	path     string // provider-relative path, "." for the node
	selector string // field selector from the leaf, "" for the leaf itself
}

// address returns the Go expression for the slot's address inside leaf.
func (r reference) address(leaf string) string {
	if r.selector == "" {
		return leaf
	}
	return "&" + leaf + "." + r.selector
}

// references lists the slots in level order, root first.
func (s *spec) references() []reference {
	var refs []reference
	for index, level := range s.levels {
		// The node of a level is reached from the leaf through the parent
		// fields of every level above it.
		var steps []string
		for above := len(s.levels) - 1; above > index; above-- {
			steps = append(steps, s.levels[above].parent)
		}
		for _, slot := range level.slots {
			selector := steps
			if slot.path != "." {
				selector = append(append([]string(nil), steps...), slot.path)
			}
			refs = append(refs, reference{
				owner: level.node, provider: slot.provider, path: slot.path,
				selector: strings.Join(selector, "."),
			})
		}
	}
	return refs
}
